package iox_test

import (
	"io"
	"os"
	"testing"

	"github.com/egdaemon/eg/internal/iox"
	"github.com/stretchr/testify/require"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestMaybeClose(t *testing.T) {
	t.Run("nil interface returns nil", func(t *testing.T) {
		var c io.Closer
		require.NoError(t, iox.MaybeClose(c))
	})

	t.Run("typed nil *os.File returns nil", func(t *testing.T) {
		var f *os.File
		var c io.Closer = f
		require.NoError(t, iox.MaybeClose(c))
	})

	t.Run("closes the closer", func(t *testing.T) {
		f, err := os.CreateTemp(t.TempDir(), "test")
		require.NoError(t, err)
		require.NoError(t, iox.MaybeClose(f))
	})

	t.Run("propagates close error on already closed file", func(t *testing.T) {
		f, err := os.CreateTemp(t.TempDir(), "test")
		require.NoError(t, err)
		require.NoError(t, f.Close())
		require.Error(t, iox.MaybeClose(f))
	})
}
